class SurfaceBinding(DeclaredFamily, affix='SurfaceBinding'):
    target = None

    def owns(self, target):
        return self.target is target and target is not None

    def prepare(self, controller) -> None:
        """No frontend means no additional application resources to acquire."""

    def prepare_terminal(self, state) -> None:
        """A detached terminal keeps its original model's configured geometry."""

    async def present_permission(self, request, view) -> None:
        """An absent frontend never acquires a permission projection."""

    def permission_changed(self, view) -> None:
        """An absent frontend has no permission bindings to invalidate."""

    async def present_failure(self, failure, view) -> None:
        """An absent frontend keeps the original failure without native work."""

    def schedule_terminal_presentation(self, controller):
        controller.start_terminal_presentation(self.target)

    def publish_terminal(self, controller, terminal_id, execution):
        """An absent frontend does not acquire native projection work."""
        return False

    @abstractmethod
    def post(self, message) -> bool:
        ...

    def close(self) -> None:
        """An absent frontend has no subscription to release."""

class PermissionRequest(DeclaredFamily, affix='PermissionRequest'):

    def __init__(self, controller):
        self.controller = controller
        self.future = asyncio.get_running_loop().create_future()
        self._projections = {}
        self.future.add_done_callback(self._completed)

    @property
    def pending(self):
        return not self.future.done()

    @property
    @abstractmethod
    def options(self) -> list[Answer]:
        ...

    @property
    @abstractmethod
    def presentation(self):
        ...

    def answer(self, binding, answer):
        if self.owns_projection(binding, binding.target):
            if answer is None or any((option.id == answer.id for option in self.options)):
                self.future.set_result(answer)

    def cancel(self):
        if self.pending:
            self.future.set_result(None)

    def current_on(self, binding, surface):
        """The original controller and surface own this attachment."""
        return self.controller.agent.controller.surface is binding and binding.owns(surface)

    def owns_projection(self, binding, surface):
        return self.pending and self.current_on(binding, surface) and (binding in self._projections)

    async def present(self, surface):
        """Acquire once before asynchronous frontend work; retain its callbacks."""
        binding = self.controller.agent.controller.surface
        if not self.pending or not self.current_on(binding, surface) or binding in self._projections:
            return
        self._projections[binding] = []
        try:
            binding.permission_changed(surface)
            await binding.present_permission(self, surface)
        except BaseException:
            self._retire_projection(binding)
            raise
        finally:
            if self.current_on(binding, surface):
                binding.permission_changed(surface)

    def watch(self, binding, retire):
        surface = binding.target
        if not self.owns_projection(binding, surface):
            retire()
            return False
        self._projections[binding].append(retire)
        return True

    def detach(self, surface):
        for binding in tuple(self._projections):
            if binding.owns(surface):
                self._retire_projection(binding)

    def _retire_projection(self, binding):
        for retire in self._projections.pop(binding, ()):
            retire()

    def _completed(self, future):
        self.controller.requests.discard(self)
        for binding in tuple(self._projections):
            self._retire_projection(binding)

    async def wait(self, timeout):
        try:
            return await asyncio.wait_for(self.future, timeout)
        except TimeoutError:
            return None

class ToolPermissionRequest(PermissionRequest):

    def __init__(self, controller, options, tool_call):
        super().__init__(controller)
        self._options = [Answer(option.name, option.option_id, option.kind) for option in options]
        self._presentation = PermissionPresentation.from_acp(tool_call)

    @property
    def options(self):
        return self._options

    @property
    def presentation(self):
        return self._presentation

class PermissionController(ClientRequestOwner):

    def __init__(self, agent):
        super().__init__(agent)
        self.requests: set[PermissionRequest] = set()

    @property
    def pending(self):
        return tuple((request for request in self.requests if request.pending))

    def request(self, options, tool_call):
        from toad.core.events import RequestPermission
        request = ToolPermissionRequest(self, options, tool_call)
        self.requests.add(request)
        self.agent.events.publish(RequestPermission())
        return request

    def present(self):
        from toad.core.events import RequestPermission
        if self.pending:
            self.agent.events.publish(RequestPermission())

    def detach(self, surface):
        for request in self.pending:
            request.detach(surface)

    def cancel(self):
        for request in self.pending:
            request.cancel()

    @classmethod
    def resolve(cls, agent):
        return agent.permissions

    @jsonrpc.expose('session/request_permission')
    async def request_permission(self, sessionId: str, options: list[protocol.PermissionOption], toolCall: protocol.ToolCallUpdate, _meta: dict | None=None) -> protocol.RequestPermissionResponse:
        cancelled = protocol.RequestPermissionResponse(outcome=protocol.DeniedOutcome(outcome='cancelled'))
        authority = ClientSessionRequest(self.agent, sessionId)
        if authority.retired:
            return cancelled
        visible = self.agent.tools.permission(toolCall)
        request = self.request(options, visible)
        answer = await request.wait(PERMISSION_TIMEOUT_SECONDS)
        if answer is None or authority.retired:
            return cancelled
        return protocol.RequestPermissionResponse(outcome=protocol.AllowedOutcome(option_id=answer.id, outcome='selected'))

class AttachedSurfaceBinding(SurfaceBinding, MroDispatch):

    def __init__(self, target, events):
        self._target = ref(target)
        self.subscription = target.subscribe_core(events)

    def prepare(self, controller) -> None:
        app = self.target.app
        controller.transcripts = controller.transcripts.with_runtime(app.preparation, app.coordination_access)
        controller.validation = ApplicationValidationOwner(app.render_processes)

    def prepare_terminal(self, state) -> None:
        target = self.target
        if target is not None:
            state.update_size(*target.get_terminal_dimensions())

    async def present_failure(self, failure, view) -> None:
        if self.owns(view):
            await self.dispatch(failure, view)

    @handles(HelpAgentFail)
    async def show_failure_help(self, failure, view):
        from toad.widgets.markdown_note import MarkdownNote
        await view.post(MarkdownNote(failure.help_text))

    @handles(LogAgentFail)
    async def show_failure_log(self, failure, view):
        from urllib.parse import quote
        from toad.widgets.agent_response import AgentResponse
        from toad.widgets.message_filter import OtherCategory
        link = AgentResponse(f'[Open ACP log]({quote(str(failure.log_path))})', show_divider=False, category=OtherCategory)
        link.add_class('-error-log-link')
        await view.post(link)

    async def present_permission(self, request, view) -> None:
        await self.dispatch(request.presentation, view, request)

    def permission_changed(self, view) -> None:
        view.refresh_bindings()

    @handles(DiffPermissionPresentation)
    async def show_file_permission(self, presentation, view, request):
        from toad.screens.permissions import PermissionReview
        screen = PermissionReview(request, view, presentation.diffs, self)
        app = view.app
        if not request.watch(self, screen.retire):
            return
        try:
            app.terminal_attention.require(screen)
            app.terminal_attention.notify(f'{view.agent_title} would like to write files', title='Permissions request', sound='question')
            result = await app.push_screen_wait(screen, mode=view.screen.id)
            request.answer(self, result)
        finally:
            app.terminal_attention.release(screen)

    @handles(InlinePermissionPresentation)
    async def show_inline_permission(self, presentation, view, request):
        from toad.widgets.acp_content import ACPToolCallContent
        from toad.tool_output import decode_content
        parts = tuple((preview for item in presentation.parts if (preview := decode_content(item).permission_preview()) is not None))

        def answer(answer):
            request.answer(self, answer)
        ask = view.ask(request.options, presentation.title, partial(ACPToolCallContent, parts) if parts else None, answer)

        def retire():
            if view.is_attached:
                view.prompt.remove_ask(ask)
                if view.prompt._ask is None:
                    view.refresh_bindings()
        request.watch(self, retire)

    def schedule_terminal_presentation(self, controller):
        if (target := self.target) is not None:
            target.call_later(controller.start_terminal_presentation, target)

    def close(self) -> None:
        if (target := self.target) is not None:
            target.retire_core(self.subscription)
        else:
            self.subscription.close()

    @property
    def target(self):
        return self._target()

    def post(self, message):
        target = self.target
        return target.post_message(message) if target is not None else False

    def publish_terminal(self, controller, terminal_id, execution):
        from toad.widgets.terminal_tool import TerminalTool
        return self.post(TerminalTool.Projection(self, controller, terminal_id, execution))

    def owns_terminal(self, projection, target):
        """Same original surface, controller lifetime and acquired address."""
        if not self.owns(target):
            return False
        return projection.controller.owner.owns_terminal_projection(self, projection)

    async def present_terminal(self, projection, target):
        if not self.owns_terminal(projection, target):
            return
        from toad.widgets.terminal_tool import TerminalTool
        if (existing := target.query_one_optional(f'#{projection.terminal_id}', TerminalTool)):
            if existing.execution is projection.execution:
                return
            await existing.remove()
            if not self.owns_terminal(projection, target):
                return
        terminal = TerminalTool(projection.execution, id=projection.terminal_id)
        await target.post(terminal)
        if not self.owns_terminal(projection, target):
            await terminal.remove()

class PermissionReview(PermissionsScreen):
    """Admission at mount uses the same pending request and source binding."""

    def __init__(self, request, view, diffs, binding):
        super().__init__(request.options, diffs, agent_name=view.agent_title or 'The Agent')
        self.request = request
        self.binding = binding
        self._view = ref(view)

    def retire(self):
        if self.is_active:
            self.dismiss(None)

    def on_screen_resume(self, event):
        self.on_mount(event)

    def on_mount(self, event):
        view = self._view()
        if not self.request.owns_projection(self.binding, view):
            event.prevent_default()
            self.retire()
